/* ====== 全局字体与变量 ====== */
@import url("https://fontsapi.zeoseven.com/237/main/result.css");
@import url("https://fontsapi.zeoseven.com/309/main/result.css");

body {
    font-family: "KingHwaOldSong";
    font-weight: normal;
} 

:root {
    --sctt: url('https://i.postimg.cc/L8673Nd1/IMG-5062.png');/*上层贴图*/
    --zctt: url('https://i.postimg.cc/HLCrBk9s/IMG-5032.png');/*中层贴图*/
    --dctt: url('https://i.postimg.cc/mg1d788q/IMG-5033.png');/*底层贴图*/
    --dlbg: url('https://i.postimg.cc/cCw3skWD/IMG-5035.png');/*顶栏背景*/
    --dl: url('https://i.postimg.cc/DZb6XgFb/IMG-5001.jpg');/*底栏背景*/
    --mbbg: url('https://i.postimg.cc/43pQ51m4/116B9EF1-035D-4B10-B171-F4BB40EFFB96.jpg');/*面板背景*/
    --logo1: url('https://i.postimg.cc/SNrsWYSh/IMG-5041.png');
    --logo2: url('https://i.postimg.cc/C1Ntv0d3/IMG-5042.png');

    /* ========== 颜色变量 ========== */
    --color1: #B1B0B0;
    --color2: #E0E0E1;
    --color3: #4A4A4A;
    --color4: #ffffff;
    --color5: #b0b0b0;
    --color6: #000;
    --color7: #bbbbbb;
    --color8: #333333;
    --color9: rgba(0,0,0,0.1);
    --color10: rgba(0,0,0,0.2);

    --text-gradient-1: var(--color1);
    --text-gradient-2: var(--color2);
    --reasoning-text: var(--color3);
    --white: var(--color4);
    --gray-light: var(--color5);
    --black: var(--color6);
    --gray-italic: var(--color7);
    --input-bg: var(--color8);
    --shadow-light: var(--color9);
    --shadow-normal: var(--color10);
    --ui-color-sec: var(--color4);

    /* ==========大部分改这里❗️❗️❗️ 🌷🌷🌷🌷🌷 ========== */
    --总体头像-左右偏移: 130px;
    --总体头像-上下偏移: 0px;
    --三元素-上下偏移: -10px;
    --头像-宽度: 105px;
    --头像-高度: 105px;

    --char头像-上下偏移: -20px;
    --char头像-左右偏移: -5px;

    --user头像-上下偏移: -20px;
    --user头像-左右偏移: -3px;

    --名字-左右偏移: -30px;
    --名字-上下偏移: -95px;
    --时间戳-左右偏移: -10px;
    --时间戳-上下偏移: -115px;



    --气泡整体-上下偏移: 15px;
    --上层气泡-左右: 193px;
    --上层气泡-上下: 0px;
    --上层气泡-宽度: 390px;
    --上层气泡-高度: 180px;

    --底部气泡-左右: -1px;
    --底部气泡-上下: -59px;
    --底部气泡-宽度: 397px;
    --底部气泡-高度: 148px;

    --中层气泡-中部左右: 0px;
    --中层气泡-中部上下: -20px;
    --中层气泡-中部宽度: 375px;

    --文字-上边距: 40px;
    --文字-右边距: 20px;
    --文字-下边距: 30px;
    --文字-左边距: 15px;

    --首页助手头像左右: 58px;
    --欢迎页助手名称: "证物01";
    --欢迎页助手信息: "「过去的痕迹，终将指向真相。」";
    --欢迎页助手头像: url("https://i.postimg.cc/QxcPZmWm/IMG-5040.jpg") center/cover no-repeat;/*🌷头像链接放入""内*/
    --欢迎页头像-上下: -30px;
    --欢迎页头像-左右: 70px;
    --欢迎页头像-宽度: 105px;
    --欢迎页头像-高度: 105px;
}
/*🌷🌷🌷想更换背景删这里的代码或者换链接❕聊天页面背景图*/
/*删这里⬇️*/
#sheld {
  background-image: url('https://i.postimg.cc/MZdd8L9F/B469F224-571E-475B-B209-80F7CE91F738.jpg');
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}
