/*====🌟🌟🌟头像、名字、时间戳🌟🌟🌟===*/
 /*by墨千尾，头像&三元素*/
/* 1. 设置 .mes 容器为垂直布局，并控制其子元素的水平对齐*/
.mes {
    display: flex !important;
    flex-direction: column !important; 
    align-items: flex-start !important; /* 让所有子项（头像信息区、消息框）默认靠左对齐，修改start为end可让所有元素靠右对其显示（头像在信息左边，整体靠右） */
    gap: 5px; /* 元素间的垂直间距 */
}
.mes .avatar {
  margin-left: var(--总体头像-左右偏移, 130px) !important;  /*🌷总体头像左右 */
  margin-top: var(--总体头像-上下偏移, 0px) !important;       /*🌷总体头像上下 */
}


/* 2. 设置头像信息区 .mesAvatarWrapper 的内部布局 */
.mes .mesAvatarWrapper {
    display: flex; /* 开启Flexbox */
    flex-direction: row; /* 水平排列（默认）*/
    align-items: center; /* 垂直居中 */
    gap: 10px; /* 头像和信息之间的间距 */
}

/* 3. 设置信息项的显示样式 */
.mesIDDisplay, .mes_timer, .tokenCounterDisplay {
    display: inline-block !important; /* 让它们可以并排显示 */
    font-size: 0.8em;
    color: #000;
    margin-right: 5px !important; /* 每个信息项之间的右边距 */
  margin-top: var(--三元素-上下偏移) !important; /*🌷三元素上下*/
}

/* 4. 确保消息框宽度为100% */
.mes .mes_block {
    width: 100%;
}

/* 头像 */
.mes .avatar {
  position: relative !important;
 /*🌷头像大小⬇️*/
    width: var(--头像-宽度) !important;
    height: var(--头像-高度) !important;


    border-radius: 50%;
    overflow: visible;
    flex-shrink: 0;
    z-index: 1;
}

/*char头像位置*/
.mes:not([is_user="true"])  .avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 0%;
    position: relative;
    z-index: 1;
  /*🌷char头像上下左右⬇️*/
    top: var(--char头像-上下偏移) !important;
    left: var(--char头像-左右偏移) !important;
    margin: 0 !important;
}

/*user头像位置*/
.mes[is_user="true"] .avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 0%;
    position: relative;
    z-index: 1;
  /*🌷user头像上下左右⬇️*/
    top: var(--user头像-上下偏移) !important;
    left: var(--user头像-左右偏移) !important;
    margin: 0 !important;
}


/*🌷名字，by不在 */
#chat .mes .name_text {
    position: absolute !important;
   /*🌷⬇️名字上下左右*/
    right: var(--名字-左右偏移) !important;
    top: var(--名字-上下偏移) !important;

    color: #000 !important;
    font-weight: 0.8 !important;
    width: 200px !important;
    text-align: center !important;
    z-index: 999999999 !important;

}

/*🌷时间戳，by不在的名字代码*/
.timestamp {
    position: absolute !important;
 /*🌷⬇️时间戳上下左右*/
    right: var(--时间戳-左右偏移) !important;
    top: var(--时间戳-上下偏移) !important;

    color: #000 !important;
    font-weight: normal !important;
    width: 200px !important;
    text-align: center !important;
    z-index: 999999999 !important;
    /* 👇旋转核心代码 */
    transform: rotate(-10deg) !important;
}
/*===顶栏部分===*/
#top-bar {
    position: fixed !important;
    top: 0;
    left: 0;
    width: 100%;
    height: 40px;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    overflow: visible !important;
    pointer-events: none;
}

#top-bar::before {
    content: "";
    position: absolute;
    top: 0;
    left: -5px;
    width: 100%;
    height: 100%;
    background: var(--dlbg) no-repeat center center / 100% 100%; 
    background-color: transparent !important;
    z-index: 7;
    pointer-events: auto;
}

#top-bar::after {
    content: "";
    position: fixed;
    top: -65px;
    right: 80px;
    width: 260px;
    height: 200px;
    background: transparent !important;
    z-index: 8;
    pointer-events: none;
}

/*图标*/
/* 顶栏图标替换by墨千尾老师 */
#top-settings-holder .drawer-icon::before {
    content: '' !important;
    visibility: hidden;
}

#top-settings-holder .drawer { flex: 1; }

#top-settings-holder .drawer-icon {
    display: block;
    margin-top: 10px;
    background-color: transparent;
    border-radius: 0px !important;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    transition: all 0.3s ease-in-out;
    width: 20px;
    height: 20px;
    opacity: 1 !important; 
}

.drawer-icon.fa-fw:hover { transform: translateY(-1.5px); }

.drawer-icon.fa-sliders,
.drawer-icon.fa-user-cog,
.drawer-icon.fa-address-card,
.drawer-icon.fa-font,
.drawer-icon.fa-cubes,
.drawer-icon.fa-plug,
.drawer-icon.fa-plug-circle-exclamation,
.drawer-icon.fa-book-atlas,
.drawer-icon.fa-panorama,
.drawer-icon.fa-face-smile {
    background-image: var(--logo1) !important;
    transform: scale(1.5); 
}

/* 展开状态图标 */
#top-settings-holder .drawer .drawer-icon.openIcon {
    background-image: var(--logo2) !important; 
    transform: scale(1.5); 
}

/*底栏*/
#send_form {
  margin-bottom: 2px;
    width: 100%;
  background-image: var(--dl) !important;
  background-repeat: no-repeat;
  background-size: cover;
  background-position: center center;
  border-radius: 8px !important;
  border: 1px solid transparent !important;
  padding: 8px;
}
/* 输入框样式 */
#send_textarea {
  border-radius: 6px !important;
  clip-path: none !important;
  background-color: var(--input-bg) !important;
  border-color: transparent !important;
}

/* ===== 输入框提示文字自定义by墨千尾老师 ===== */
#nonQRFormItems {
  position: relative;
}
#send_textarea::placeholder {
  color: transparent !important;
  text-shadow: none !important; 
}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  content: "police time";
  background: linear-gradient(to right, var(--text-gradient-1), var(--text-gradient-2));
  -webkit-background-clip: text;
  color: transparent;
  position: absolute; 
  left: 55%;
  top: 50%;
  transform: translate(-50%, -50%); 
  font-style: normal; 
  font-size: 0.5em; 
  pointer-events: none;
  z-index: 10;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: calc(100% - 30px);
}

/* --- 底部按键图标替换 --- */
#options_button::before, #extensionsMenuButton::before, #send_but::before, #quick-reply-rocket-button > i { display: none !important; }
#options_button, #extensionsMenuButton, #send_but, #quick-reply-rocket-button {
    width: 30px !important;
    height: 28px !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    background-color: transparent;
    border-radius: 0px !important;
    opacity: 1 !important;
}
#options_button, #extensionsMenuButton { background-image: var(--logo1); }
#send_but { background-image: var(--logo2); }
#quick-reply-rocket-button { background-image: var(--logo1); }

/*面板背景*/
.drawer-content {
  background: var(--mbbg) center/cover fixed no-repeat;

}

/*————气泡————*/
.mes {
    width: 390px !important;
    padding: 40px 12px;
    margin-bottom: 125px!important;
 /*🌷气泡整体上下⬇️*/
margin-top: var(--气泡整体-上下偏移) !important;

    display: flex;
    flex-direction: column;
    align-items: center;
    background-color: rgba(255, 255, 255, 0) !important;
    border:none!important;
    border-radius: 0;    
    box-shadow: none;    
    position: relative;
    overflow: visible !important;

}

/* 上层气泡 */
.mes::after {
    content: "";
    position: absolute; 
    left: var(--上层气泡-左右);/*🌷左右*/
    transform: translateX(-50%);
    top: var(--上层气泡-上下);/*🌷上下*/
    width: var(--上层气泡-宽度);/*🌷宽，没变化就改height*/
    height: var(--上层气泡-高度);
    background-image: var(--sctt);
    background-size: cover;
    background-repeat: no-repeat;
    opacity: 1 !important;
    pointer-events: none;
    z-index: 2;
}

/* 底部气泡 */
.mes::before {
    content: "";
    position: absolute;
    left: var(--底部气泡-左右);/*🌷左右*/
    bottom: var(--底部气泡-上下);/*🌷上下*/
    width: var(--底部气泡-宽度);/*🌷宽，没变化就改height*/
    height: var(--底部气泡-高度);
    background: var(--dctt);
    background-size: contain;  
    background-repeat: no-repeat;
    background-position: center center; 
    opacity: 1 !important;
    pointer-events: none;
    z-index: 99;
}

/*中间｜不需要动，豆包给的一坨😵 */
.mes_block {
    width: 390px !important;
    max-width: none !important;
    background: transparent !important;
    background-repeat: repeat-y !important;
    background-size: 390px auto !important;
    background-position: 0px 0 !important;
    border-radius: 0 !important;
    padding: var(--文字-上边距) var(--文字-右边距) var(--文字-下边距) var(--文字-左边距) !important;/*🌷文字边距*/
    position: relative !important;
    margin-top: 0 !important;
    min-height: 100px;
    overflow: visible !important;
    z-index: 3 !important;
}

/* 中层气泡*/
.mes_block::before {
    content: '' !important;
    position: absolute !important;
    left: var(--中层气泡-中部左右) !important;/*🌷气泡中部左右*/
    top: var(--中层气泡-中部上下) !important;/*🌷气泡中部上下*/
    width: var(--中层气泡-中部宽度) !important;/*🌷气泡中部宽度*/
    height: calc(100% - 0px) !important;
    background: var(--zctt) !important;
    background-repeat: repeat-y !important;
    background-size: 100% auto !important;
    z-index: -1 !important;
}






/* 文本框与下一个头像框隔开 */
.mes {
  margin-bottom: 10em !important; 
  clear: both !important; 
}

/* by墨千尾老师，让消息框里的文字铺满消息框 */
.mes .mes_text {
    width: 100%;
    padding: 20px 10px 0px 0px;
    margin: 0px 0px 0px 0px;
}

/*思维链内文字*/
.mes_reasoning {
    font-weight: 220; 
    line-height: 1.7; 
    text-align: justify; 
    --top-padding: 0rem;    /* 文字 离 顶部 的距离 */
    --bottom-padding: 1rem; /* 文字 离 底部 的距离 */
    --left-padding: 0.1rem;     /* 文字 离 左边 的距离 */
    --right-padding: 0.1rem;  /* 文字 离 右边 的距离 */

    padding: var(--top-padding) var(--right-padding) var(--bottom-padding) var(--left-padding);
}

/*思维链*/
/* by12老师，隐藏思维链背景 */
#chat .mes .mes_reasoning_header {
  background: transparent !important; /* 背景改为透明 */
  border: none !important; /* 移除边框 */
  box-shadow: none !important; /* 移除阴影 */
  border-radius: 0; /* 移除圆角 */
  backdrop-filter: none !important; 
  -webkit-backdrop-filter: none !important; 
  padding: 0 !important; /* 移除内边距 */
  margin-bottom: 0 !important; /* 移除底部外边距 */
  color: var(--reasoning-text) !important; /* 字体颜色自定义 */
  font-size: 1em !important;/* 字体大小 */
  display: inline-flex !important;
  align-items: center !important;
  transition: none !important; 
}

/*byhy老师，隐藏箭头 */
.mes_reasoning_arrow {
    display: none !important;
}

/*byN老师*/
.mes_reasoning_header_title::before {
    content: "" !important;
    width: 120px !important;
    height: 40px !important;
    background-image: var(--logo1) !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    display: inline-block !important;
    vertical-align: middle !important;
}
.mes_reasoning_header_title {
    font-size: 0 !important;
}

/*图标统一替换*/
/* 小铅笔 */
.fa-pencil-alt::before, .fa-pencil::before {
  display: none !important;
}
.fa-pencil-alt, .fa-pencil {
  background: var(--logo2) no-repeat center/contain !important;
  width: 25px !important;
  height: 25px !important;
  display: inline-block;
  vertical-align: middle;
  opacity: 1 !important;
  transition: opacity 0.3s ease !important;
}

/* 三个点 */
.fa-ellipsis-h::before, .fa-ellipsis::before {
  display: none !important;
}
.fa-ellipsis-h, .fa-ellipsis {
  background: var(--logo2) no-repeat center/contain !important;
  width: 25px !important;
  height: 25px !important;
  display: inline-block;
  vertical-align: middle;
  opacity: 1 !important;
  transition: opacity 0.3s ease !important;
}

.fa-pencil-alt:hover, 
.fa-pencil:hover, 
.fa-ellipsis-h:hover, 
.fa-ellipsis:hover {
  opacity: 1 !important;
}


/*滑块图标*/
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 30px !important; 
    height: 30px !important; 
    background: var(--logo1) center/contain no-repeat !important;
    background-color: transparent !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    cursor: ew-resize !important;
    position: relative !important;
    z-index: 999 !important;
    opacity: 1 !important;

    /* 去灰、保持原色 */
    filter: none !important;
    -webkit-filter: none !important;
    background-blend-mode: normal !important;
}

/*预设编辑*/
.neo-range-slider {
    height: 3px !important;
    background: linear-gradient(90deg, var(--white), var(--gray-light), var(--white)) !important;
    box-shadow: inset 0 0 3px var(--shadow-normal) !important;
    cursor: ew-resize !important;
    z-index: 1;
    margin-bottom: 0px !important;
    border-radius: 0px !important;
}

.prompt-manager-edit-action::before {
  display: none !important;
}
.prompt-manager-edit-action {
  background: var(--logo1) no-repeat center/20px 25px !important;
  width: 20px !important;
  height: 25px !important;
  opacity: 1 !important;
}

/*文字*/
/* 正文（全局白色） */
.mes {
  color: #e0e0e0 !important;
}

/* 引用文本 */
.mes q {
  background: rgba(255,255,255,0.05) !important;
  color: #c0c0c0 !important;
  border: none !important;
  padding: 5px 10px !important;
  font-style: normal !important;
  border-radius: 4px !important;
  box-shadow: none !important;
  display: inline-block !important;
}

/* 斜体文本 浅灰 */
.mes i,
.mes em {
  color: #a0a0a0 !important;
  text-decoration: none !important;
}

/* 下划线文本 */
.mes u {
  text-decoration: none !important;
  color: #ffffff !important;
  font-weight: normal !important;
  padding: 3px 6px !important;
  border-radius: 4px !important;
  background: rgba(255,255,255,0.08) !important;
  border-bottom: none !important;
}

/*===by12老师===*/
/* 收藏区左右滑动 */
#HotSwapWrapper {
  overflow: hidden;
}
#HotSwapWrapper > div {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  overflow-y: hidden;
  height: calc(var(--avatar-base-height) + 10px);
}

body.big-avatars #HotSwapWrapper > div {
  height: calc(var(--avatar-base-height) * var(--big-avatar-height-factor) + 10px);
}
#HotSwapWrapper > div::-webkit-scrollbar {
  height: 5px; 
}
#HotSwapWrapper > div::-webkit-scrollbar-thumb {
  background-color: var(--ui-color-sec) !important; 
  border-radius: 5px !important; 
}
.character_select.is_fav .avatar {
  outline: 2px solid var(--color4) !important;
}

/* 收藏角色名字 */
.character_select.is_fav .ch_name {
  color: var(--color4) !important;
  text-shadow: 0 0 6px var(--color4), 0 0 12px var(--color4), 0 0 24px var(--color4) !important;
}

